<?php
class BookingController extends Controller{private function model(){require_once __DIR__.'/../models/Booking.php';return new Booking();}public function index(){require_login();$m=$this->model();$bookings=in_array(current_user_role(),['Admin','Staff'])?$m->all():$m->byUser(current_user_id());$this->view('bookings/index',compact('bookings'));}public function create(){require_role(['Customer','Admin']);require_once __DIR__.'/../models/Property.php';$property=(new Property())->find($_GET['property_id']??0);if(!$property)die('Property not found.');$this->view('bookings/form',['booking'=>null,'property'=>$property,'action'=>url('bookings/store')]);}public function store(){verify_csrf();require_role(['Customer','Admin']);$pid=$_POST['property_id'];$in=$_POST['check_in_date'];$out=$_POST['check_out_date'];if(!Validation::notPast($in)||!Validation::dateOrder($in,$out)){Session::flash('error','Invalid dates.');$this->redirect('properties');}if($this->model()->hasConflict($pid,$in,$out)){Session::flash('error','Already booked for those dates.');$this->redirect('properties');}$this->model()->create(['user_id'=>current_user_id(),'property_id'=>$pid,'check_in_date'=>$in,'check_out_date'=>$out,'notes'=>$_POST['notes']??'']);Session::flash('success','Booking submitted.');$this->redirect('bookings');}public function edit(){require_login();$booking=$this->model()->find($_GET['id']);if(current_user_role()==='Customer'&&$booking['user_id']!=current_user_id())die('Access denied.');require_once __DIR__.'/../models/Property.php';$property=(new Property())->find($booking['property_id']);$this->view('bookings/form',['booking'=>$booking,'property'=>$property,'action'=>url('bookings/update?id='.$_GET['id'])]);}public function update(){verify_csrf();require_login();$b=$this->model()->find($_GET['id']);if(current_user_role()==='Customer'&&$b['user_id']!=current_user_id())die('Access denied.');$in=$_POST['check_in_date'];$out=$_POST['check_out_date'];if(!Validation::notPast($in)||!Validation::dateOrder($in,$out)){Session::flash('error','Invalid dates.');$this->redirect('bookings');}$this->model()->updateDates($_GET['id'],['check_in_date'=>$in,'check_out_date'=>$out,'notes'=>$_POST['notes']??'']);Session::flash('success','Booking updated.');$this->redirect('bookings');}public function delete(){require_login();$this->model()->delete($_GET['id']);Session::flash('success','Booking deleted.');$this->redirect('bookings');}public function approve(){require_role(['Admin','Staff']);$this->model()->updateStatus($_GET['id'],'Confirmed');$this->redirect('bookings');}public function cancel(){require_role(['Admin','Staff']);$this->model()->updateStatus($_GET['id'],'Cancelled');$this->redirect('bookings');}}
